<?php
require __DIR__.'/app.php';$u=current_user();if(!$u||$u['role']!=='admin'){http_response_code(403);exit('Akses ditolak');}
if(isset($_POST['approve'])){verify_csrf();$id=(int)$_POST['approve'];db()->prepare("UPDATE videos SET status='approved' WHERE id=?")->execute([$id]);flash('Video disetujui dan tampil publik.');header('Location: admin.php');exit;}
if(isset($_POST['reject'])){verify_csrf();$id=(int)$_POST['reject'];db()->prepare("UPDATE videos SET status='rejected' WHERE id=?")->execute([$id]);flash('Video ditolak.');header('Location: admin.php');exit;}
$rows=db()->query("SELECT v.*,u.username FROM videos v JOIN users u ON u.id=v.user_id WHERE v.status='pending' ORDER BY v.id ASC")->fetchAll();
?><!doctype html><html lang="id"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css"><title>Admin VideoEarn</title><body><main class="content"><h1>Moderasi Video</h1><p><a href="index.php">← Kembali ke aplikasi</a></p><?php foreach($rows as $v):?><div class="panel"><b>@<?=e($v['username'])?></b><p><?=e($v['caption'])?></p><small><?=e($v['drive_file_id'])?></small><p><a class="button" target="_blank" href="https://drive.google.com/file/d/<?=e($v['drive_file_id'])?>/view">Lihat di Drive</a> <form method="post" style="display:inline"><?=csrf_field()?> <button class="button" name="approve" value="<?=$v['id']?>">Setujui</button> <button class="button danger" name="reject" value="<?=$v['id']?>">Tolak</button></form></p></div><?php endforeach;if(!$rows):?><p class="muted">Tidak ada video menunggu moderasi.</p><?php endif;?></main></body></html>
